// GuiGraphics.enableScissor uses GUI-scaled screen coordinates and does
// not follow the pose-stack transform used to draw this canvas. Project
// the logical meter bounds through the same view transform first.
var scissor = view.screenBounds(x0, top, x1, y1);
graphics.enableScissor(scissor.left(), scissor.top(), scissor.right(), scissor.bottom());

/**
 * Convert a canvas-local rectangle to the GUI-scaled screen coordinates
 * expected by GuiGraphics.enableScissor. Unlike draw coordinates, the
 * scissor stack is not transformed by the active pose stack.
 */
public ScissorBounds screenBounds(double left, double top, double right, double bottom) {
   if (!Double.isFinite(left) || !Double.isFinite(top) || !Double.isFinite(right)
      || !Double.isFinite(bottom) || right <= left || bottom <= top) {
      throw new IllegalArgumentException("Scissor rectangle must be finite and non-empty");
   }
   return new ScissorBounds((int)Math.floor(this.screenX(left)), (int)Math.floor(this.screenY(top)),
      (int)Math.ceil(this.screenX(right)), (int)Math.ceil(this.screenY(bottom)));
}

public record ScissorBounds(int left, int top, int right, int bottom) {
   public ScissorBounds {
      if (right <= left || bottom <= top) throw new IllegalArgumentException("Scissor bounds must be non-empty");
   }
}

public void scissorBoundsFollowCanvasTransformInGuiScaledScreenCoordinates() {
   for (int[] viewport : new int[][] {{1280, 260}, {1280, 720}}) {
      var view = FreezerReferenceGeometry.fitCanvas(viewport[0], viewport[1], 347, 381, 0.78F);
      var bounds = view.screenBounds(56, 89, 77, 192);
      assertEquals((int)Math.floor(view.screenX(56)), bounds.left());
      assertEquals((int)Math.floor(view.screenY(89)), bounds.top());
      assertEquals((int)Math.ceil(view.screenX(77)), bounds.right());
      assertEquals((int)Math.ceil(view.screenY(192)), bounds.bottom());
      // The real 7-segment art sits inside the local meter bounds. The
      // projected clip must include it even when the canvas is scaled.
      assertTrue(bounds.left() <= view.screenX(62.3));
      assertTrue(bounds.right() > view.screenX(72));
      assertTrue(bounds.top() <= view.screenY(124));
      assertTrue(bounds.bottom() >= view.screenY(186));
      assertTrue("screen-space scissor must not be mistaken for canvas-local coordinates", bounds.left() > 56);
   }
}

